import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('Montserrat');

const { fontFamily } = loadFont();



export type GlowingTextIntroProps = Record<string, any>;

const GlowingTextIntro: React.FC<GlowingTextIntroProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false, // Set to false to enforce the black and yellow theme by default
  durationInSeconds = 5,
  text = "?", // Changed default text to a question mark
  textColor = "#FFE600", // Bright yellow
  glowColor = "rgba(255, 230, 0, 0.4)", // Yellow glow
  glowSpreadMax = 180,
  glowSpreadIdle = 60,
  yOffsetPercent = 30, // Centered vertically for a large element
  fontSize = 450, // Scaled up significantly for a single character
  letterSpacing = 0,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Bouncy pop-up animation for the question mark
  const scale = spring({
    fps,
    frame,
    config: {
      damping: 9, // Lower damping for a noticeable bounce
      stiffness: 220, // Snappy entry
      mass: 0.8,
    },
  });

  const opacity = interpolate(frame, [0, 3], [0, 1], {
    extrapolateRight: "clamp",
  });

  // Pops up from below its final resting position
  const yPop = interpolate(frame, [0, 8], [height * 0.15, 0], {
    extrapolateRight: "clamp",
  });

  // Quick initial flash of glow on impact, settling to idle glow
  const glowSpread = interpolate(
    frame,
    [0, 6, 25],
    [0, glowSpreadMax, glowSpreadIdle],
    { extrapolateRight: "clamp" }
  );

  const textShadow = `
    0 0 ${glowSpread * 0.25}px ${glowColor},
    0 0 ${glowSpread * 0.5}px ${glowColor},
    0 0 ${glowSpread}px ${glowColor},
    0 0 ${glowSpread * 1.5}px ${glowColor}
  `;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "flex-start",
        alignItems: "center",
      }}
    >
      <div
        style={{
          marginTop: `${yOffsetPercent}%`,
          fontFamily,
          fontSize: `${fontSize}px`,
          fontWeight: 900,
          color: textColor,
          textTransform: "uppercase",
          textShadow,
          opacity,
          transform: `translateY(${yPop}px) scale(${scale})`,
          textAlign: "center",
          letterSpacing: `${letterSpacing}px`,
          lineHeight: 1.1,
          maxWidth: width * 0.85,
          transition: "none",
        }}
      >
        {text}
      </div>
    </AbsoluteFill>
  );
};

export default GlowingTextIntro;